# Reads the algorithm name from each ciphertext's header; not part of the SDK API.
import json, time
from cryptoserve import CryptoServe

crypto = CryptoServe(app_name="my-app", contexts=["user-pii", "payment-data"])

def algorithm(ciphertext):
    size = int.from_bytes(ciphertext[:2], "big")
    header = json.loads(ciphertext[2:2 + size])
    return header.get("alg") or header.get("mode")

for context in ["user-pii", "payment-data"]:
    for usage in [None, "at_rest", "in_transit", "in_use", "streaming", "disk"]:
        try:
            print(context, usage, algorithm(crypto.encrypt(b"x", context=context, usage=usage)))
        except Exception as e:
            print(context, usage, "error:", e)
        time.sleep(1.5)
